import { useRecoilValue } from "recoil";
import { toDoListState, toDoSelector } from "../atoms";
import CreateToDo from "./CreateToDo";
import ToDo from "./ToDo";
import styled from "styled-components";

const Container = styled.div`
	padding: 20px;
	max-width: 480px;
	margin: 0 auto;
`;

const Header = styled.header`
	height: 20vh;
	display: flex;
  justify-content: center;
  align-items: center;
	h1 {
		font-size: 40px;
		font-weight: bolder;
		color: ${(props) => props.theme.textColors.normal}
	}
`;

const Tabs = styled.div`
	display: flex;
  margin: 25px 0px;
  gap: 12px;
	justify-content: center;
`;

const Tab = styled.button`
  text-align: center;
  /* text-transform: uppercase; */
  font-size: 12px;
  font-weight: 400;
  padding: 6px 20px;
  border-radius: 12px;
	background-color: ${(props) => props.theme.bgColors.dimmed};
  color: ${(props) => props.theme.textColors.normal};
	/* border-bottom: 1px solid ;
	border-color: transparent;
	*/
	 &:active {
		color: ${ ( props ) => props.theme.brandColors.primary }
	 }
	 &:hover {

	 }
`;


function ToDoList() {
  const toDos = useRecoilValue(toDoListState);
	const [to_do, doing, done] = useRecoilValue(toDoSelector);

  return (
    <Container>
      <Header>
				<h1>To Do List</h1>
			</Header>
			<Tabs>
				<Tab>all</Tab>
				<Tab>to do</Tab>
				<Tab>in progress</Tab>
				<Tab>done</Tab>
			</Tabs>

      {/* <hr /> */}
      <CreateToDo />
			<div style={{display: "flex", gap: 10}}>
				<ul style={{minWidth: 100, backgroundColor: "#000", gap: "10px"}}>
        {to_do.map((toDo) => (
          <ToDo key={toDo.id} {...toDo} />
        ))}
				</ul>
				<ul style={{minWidth: 100, backgroundColor: "#000"}}>
					{doing.map((toDo) => (
						<ToDo key={toDo.id} {...toDo} />
					))}
				</ul>
				<ul style={{minWidth: 100, backgroundColor: "#000"}}>
					{done.map((toDo) => (
						<ToDo key={toDo.id} {...toDo} />
					))}
				</ul>
			</div>
		</Container>
  );
}

export default ToDoList;
